#!/usr/bin/env bash
set -euo pipefail
WORKSPACE=${WORKSPACE:-/home/kavia/workspace/code-generation/lms_dt3-307785-309186/LMSDatabase(MongoDB)}
mkdir -p "$WORKSPACE" && cd "$WORKSPACE"
INITJS="$WORKSPACE/init-lms.js"
if [ -f "$INITJS" ] && [ "${FORCE:-0}" != "1" ]; then echo "Init exists (set FORCE=1 to overwrite)"; exit 0; fi
cat > "$INITJS" <<'JS'
// idempotent initializer compatible with mongo/mongosh --file
(function(){
  const DBNAME = (typeof DBNAME !== 'undefined') ? DBNAME : 'lmstest';
  const _db = (typeof db !== 'undefined') ? db.getSiblingDB(DBNAME) : typeof connect === 'function' ? connect(DBNAME) : null;
  if (!_db) { print('No DB shell context available'); throw 'No DB context'; }
  const existing = (typeof _db.getCollectionInfos === 'function') ? _db.getCollectionInfos().map(c=>c.name) : _db.getCollectionNames();
  if (!existing.includes('users')) _db.createCollection('users');
  if (!existing.includes('courses')) _db.createCollection('courses');
  try { _db.users.createIndex({ email: 1 }, { unique: true }); } catch(e){ print('users index: '+e); }
  try { _db.courses.createIndex({ courseCode: 1 }, { unique: true }); } catch(e){ print('courses index: '+e); }
  print('LMS init completed for DB: ' + DBNAME);
})();
JS
chmod 600 "$INITJS"
echo "Wrote $INITJS"
